import{_ as i,a0 as l,w as g,s as m,ao as o,I as e,x as p,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"使用条块化I/O管理多个LVM磁盘（第五部分） | LCTT x X-CMD","titleTemplate":false,"description":"使用条块化I/O管理多个LVM磁盘（第五部分） | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用条块化I/O管理多个LVM磁盘（第五部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用条块化I/O管理多个LVM磁盘（第五部分） | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V","title":"使用条块化I/O管理多个LVM磁盘（第五部分）","tag":"201412","desc":""},"relativePath":"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V.md","filePath":"[post].md"}'),a={name:"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V.md"};function d(u,t,w,v,V,L){const n=l("Link");return g(),m("div",null,[t[30]||(t[30]=o(`<h1 id="使用条块化i-o管理多个lvm磁盘-第五部分" tabindex="-1">使用条块化I/O管理多个LVM磁盘（第五部分） <a class="header-anchor" href="#使用条块化i-o管理多个lvm磁盘-第五部分" aria-label="Permalink to “使用条块化I/O管理多个LVM磁盘（第五部分）”">​</a></h1><p>在本文中，我们将了解逻辑卷是如何通过条块化I/O来写入数据到磁盘的。逻辑卷管理的酷炫特性之一，就是它能通过条块化I/O跨多个磁盘写入数据。</p><h3 id="lvm条块化是什么" tabindex="-1">LVM条块化是什么？ <a class="header-anchor" href="#lvm条块化是什么" aria-label="Permalink to “LVM条块化是什么？”">​</a></h3><p><strong>LVM条块化</strong>是LVM功能之一，该技术会跨多个磁盘写入数据，而不是对单一物理卷持续写入。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/LVM-Striping.jpeg" alt="Manage LVM Disks Using Striping I/O"></p><p><em>使用条块化I/O管理LVM磁盘</em></p><h4 id="条块化特性" tabindex="-1">条块化特性 <a class="header-anchor" href="#条块化特性" aria-label="Permalink to “条块化特性”">​</a></h4><ul><li>它会改善磁盘性能。</li><li>避免对单一磁盘的不断的大量写入。</li><li>使用对多个磁盘的条块化写入，可以减少磁盘填满的几率。</li></ul><p>在逻辑卷管理中，如果我们需要创建一个逻辑卷，扩展的卷会完全映射到卷组和物理卷。在此种情形中，如果其中一个<strong>PV</strong>（物理卷）被填满，我们需要从其它物理卷中添加更多扩展。这样，添加更多扩展到PV中后，我们可以指定逻辑卷使用特定的物理卷写入I/O。</p><p>假设我们有<strong>四个磁盘</strong>驱动器，分别指向了四个物理卷，如果各个物理卷总计可以达到<strong>100 I/O</strong>，我们卷组就可以获得<strong>400 I/O</strong>。</p><p>如果我们不使用<strong>条块化方法</strong>，文件系统将横跨基础物理卷写入。例如，写入一些数据到物理卷达到100 I/O，这些数据只会写入到第一个PV（<strong>sdb1</strong>）。如果我们在写入时使用条块化选项创建逻辑卷，它会分割100 I/O分别写入到四个驱动器中，这就是说每个驱动器中都会接收到25 I/O。</p><p>这会在循环过程中完成。如果这些逻辑卷其中任何一个需要扩展，在这种情形下，我们不能添加1个或2个PV，必须添加所有4个pv来扩展逻辑卷大小。这是条块化特性的缺点之一，从中我们可以知道，在创建逻辑卷时，我们需要为所有逻辑卷分配相同的条块大小。</p><p>逻辑卷管理有着这些特性，它使我们能够同时在多个pv中条块化数据。如果你对逻辑卷熟悉，你可以去设置逻辑卷条块化。反之，你则必须了解逻辑卷管理的基础知识了，请阅读更基础的文章来了解逻辑卷管理。</p><h4 id="我的服务器设置" tabindex="-1">我的服务器设置 <a class="header-anchor" href="#我的服务器设置" aria-label="Permalink to “我的服务器设置”">​</a></h4><p>这里，我使用<strong>CentOS6.5</strong>用作练习。下面这些步骤也适用于RHEL、Oracle Linux以及大多数发行版。</p><pre><code>操作系统：	   CentOS 6.5
IP地址：		192.168.0.222
主机名：	    tecmint.storage.com
</code></pre><h3 id="条块化i-o的逻辑卷管理" tabindex="-1">条块化I/O的逻辑卷管理 <a class="header-anchor" href="#条块化i-o的逻辑卷管理" aria-label="Permalink to “条块化I/O的逻辑卷管理”">​</a></h3><p>出于演示目的，我已经准备了4个硬盘驱动器，每个驱动器1GB大小。让我用下面的‘<strong>fdisk</strong>’命令来列给你看看吧。</p><pre><code># fdisk -l | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Hard-Drives.png" alt="List Hard Drives"></p><p><em>列出硬盘驱动器</em></p>`,21)),e("p",null,[t[1]||(t[1]=p("现在，我们必须为这4个硬盘驱动器",-1)),t[2]||(t[2]=e("strong",null,"sdb",-1)),t[3]||(t[3]=p("，",-1)),t[4]||(t[4]=e("strong",null,"sdc",-1)),t[5]||(t[5]=p("，",-1)),t[6]||(t[6]=e("strong",null,"sdd",-1)),t[7]||(t[7]=p("和",-1)),t[8]||(t[8]=e("strong",null,"sde",-1)),t[9]||(t[9]=p("创建分区，我们将用‘",-1)),t[10]||(t[10]=e("strong",null,"fdisk",-1)),t[11]||(t[11]=p("’命令来完成该工作。要创建分区，请遵从本文",-1)),e("strong",null,[s(n,{href:"http://linux.cn/article-3965-1.html"},{default:r(()=>[...t[0]||(t[0]=[p("第一部分",-1)])]),_:1})]),t[12]||(t[12]=p("中",-1)),t[13]||(t[13]=e("strong",null,"步骤#4",-1)),t[14]||(t[14]=p("的说明，并在创建分区时确保你已将类型修改为",-1)),t[15]||(t[15]=e("strong",null,"LVM（8e）",-1)),t[16]||(t[16]=p("。",-1))]),t[31]||(t[31]=o(`<pre><code># pvcreate /dev/sd[b-e]1 -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-Physical-Volumes-in-LVM.png" alt="Create Physical Volumes in LVM"></p><p><em>在LVM中创建物理卷</em></p><p>PV创建完成后，你可以使用‘<strong>pvs</strong>’命令将它们列出来。</p><pre><code># pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Verify-Physical-Volumes.png" alt="Verify Physical Volumes"></p><p><em>验证物理卷</em></p><p>现在，我们需要使用这4个物理卷来定义卷组。这里，我定义了一个物理扩展大小（PE）为<strong>16MB</strong>，名为<strong>vg_strip</strong>的卷组。</p><pre><code># vgcreate -s 16M vg_strip /dev/sd[b-e]1 -v
</code></pre><p>上面命令中选项的说明：</p><ul><li><strong>[b-e]1</strong> – 定义硬盘驱动器名称，如sdb1，sdc1，sdd1，sde1。</li><li><strong>-s</strong> – 定义物理扩展大小。</li><li><strong>-v</strong> – 详情。</li></ul><p>接下来，验证新创建的卷组：</p><pre><code># vgs vg_strip
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Verify-Volume-Group.png" alt="Verify Volume Group"></p><p><em>验证卷组</em></p><p>要获取VG更详细的信息，可以在<strong>vgdisplay</strong>命令中使用‘-v’选项，它将给出<strong>vg_strip</strong>卷组中所使用的全部物理卷的详细情况。</p><pre><code># vgdisplay vg_strip -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Volume-Group-Information.png" alt="Volume Group Information"></p><p><em>卷组信息</em></p><p>回到我们的话题，现在在创建逻辑卷时，我们需要定义条块化值，就是数据需要如何使用条块化方法来写入到我们的逻辑卷中。</p><p>这里，我创建了一个名为<strong>lv_tecmint-strp1</strong>，大小为<strong>900MB</strong>的逻辑卷，它需要放到<strong>vg_strip</strong>卷组中。我定义了4个条块，就是说数据在写入到我的逻辑卷时，需要条块化分散到4个PV中。</p><pre><code># lvcreate -L 900M -n lv_tecmint_strp1 -i4 vg_strip
</code></pre><ul><li><strong>-L</strong> –逻辑卷大小</li><li><strong>-n</strong> –逻辑卷名称</li><li><strong>-i</strong> –条块化</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-Logical-Volumes.png" alt="Create Logical Volumes"></p><p><em>创建逻辑卷</em></p><p>在上面的图片中，我们可以看到条块尺寸的默认大小为<strong>64 KB</strong>，如果我们需要自定义条块值，我们可以使用<strong>-I</strong>（大写I）。要确认逻辑卷已经是否已经创建，请使用以下命令。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Confirm-Logical-Volumes.png" alt="Confirm Logical Volumes"></p><p><em>确认逻辑卷</em></p><p>现在，接下来的问题是，我们怎样才能知道条块被写入到了4个驱动器。这里，我们可以使用‘<strong>lvdisplay</strong>’和<strong>-m</strong>（显示逻辑卷映射）命令来验证。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp1 -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Check-Logical-Volumes.png" alt="Check Logical Volumes"></p><p><em>检查逻辑卷</em></p><p>要创建自定义的条块尺寸，我们需要用我们自定义的条块大小<strong>256KB</strong>来创建一个<strong>1GB</strong>大小的逻辑卷。现在，我打算将条块分布到3个PV上。这里，我们可以定义我们想要哪些pv条块化。</p><pre><code># lvcreate -L 1G -i3 -I 256 -n lv_tecmint_strp2 vg_strip /dev/sdb1 /dev/sdc1 /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Define-Stripe-Size.png" alt="Define Stripe Size"></p><p><em>定义条块大小</em></p><p>接下来，检查条块大小和条块化的卷。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp2 -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Check-Stripe-Size.png" alt="Check Stripe Size"></p><p><em>检查条块大小</em></p><p>是时候使用设备映射了，我们使用‘<strong>dmsetup</strong>’命令来完成这项工作。它是一个低级别的逻辑卷管理工具，它用于管理使用了设备映射驱动的逻辑设备。</p><pre><code># dmsetup deps /dev/vg_strip/lv_tecmint_strp[1-2]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Device-Mapper.png" alt="Device Mapper"></p><p><em>设备映射</em></p><p>这里，我们可以看到strp1依赖于4个驱动器，strp2依赖于3个设备。</p><p>希望你已经明白，我们怎样能让逻辑卷条块化来写入数据。对于此项设置，必须掌握逻辑卷管理基础知识。</p><p>在我的下一篇文章中，我将给大家展示怎样在逻辑卷管理中迁移数据。到那时，请静候更新。同时，别忘了对本文提出有价值的建议。</p><hr>`,49)),e("p",null,[t[18]||(t[18]=p("via: ",-1)),s(n,{href:"http://www.tecmint.com/manage-multiple-lvm-disks-using-striping-io/"},{default:r(()=>[...t[17]||(t[17]=[p("http://www.tecmint.com/manage-multiple-lvm-disks-using-striping-io/",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=p("作者：",-1)),s(n,{href:"http://www.tecmint.com/author/babinlonston/"},{default:r(()=>[...t[19]||(t[19]=[p("Babin Lonston",-1)])]),_:1}),t[23]||(t[23]=p(" 译者：",-1)),s(n,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[20]||(t[20]=[p("GOLinux",-1)])]),_:1}),t[24]||(t[24]=p(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[21]||(t[21]=[p("wxy",-1)])]),_:1})]),e("p",null,[t[27]||(t[27]=p("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[25]||(t[25]=[p("LCTT",-1)])]),_:1}),t[28]||(t[28]=p(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/"},{default:r(()=>[...t[26]||(t[26]=[p("Linux中国",-1)])]),_:1}),t[29]||(t[29]=p(" 荣誉推出",-1))])])}const c=i(a,[["render",d]]);export{I as __pageData,c as default};
